//! Body files for capture records, handoffs and rule responses.
//!
//! All keys are generated by the server. This module rejects anything that is
//! not an opaque identifier, so a caller can never turn a key into a path.

use crate::error::{AppError, AppResult, IoPath};
use std::path::{Path, PathBuf};
use tokio::io::{AsyncReadExt, AsyncSeekExt, AsyncWriteExt};

const MAX_ID_LEN: usize = 128;

#[derive(Clone)]
pub struct BodyStore {
    root: PathBuf,
}

impl BodyStore {
    pub async fn new(root: PathBuf) -> AppResult<Self> {
        for dir in [root.join("tmp"), root.join("handoffs"), root.join("rules")] {
            tokio::fs::create_dir_all(&dir).await.with_path(&dir)?;
            set_private_dir(&dir).await;
        }
        set_private_dir(&root).await;
        Ok(Self { root })
    }

    #[must_use]
    pub fn root(&self) -> &Path {
        &self.root
    }

    fn record_path(&self, record_id: &str) -> AppResult<PathBuf> {
        Ok(self
            .root
            .join("tmp")
            .join(format!("{}.bin", validate_id(record_id)?)))
    }

    fn sample_path(&self, rule_id: &str, revision: u32) -> AppResult<PathBuf> {
        Ok(self
            .root
            .join("rules")
            .join(validate_id(rule_id)?)
            .join(format!("{revision}.sample.bin")))
    }

    fn handoff_path(&self, handoff_id: &str) -> AppResult<PathBuf> {
        Ok(self
            .root
            .join("handoffs")
            .join(validate_id(handoff_id)?)
            .join("response.bin"))
    }

    fn rule_path(&self, rule_id: &str, revision: u32) -> AppResult<PathBuf> {
        Ok(self
            .root
            .join("rules")
            .join(validate_id(rule_id)?)
            .join(format!("{revision}.bin")))
    }

    pub async fn write_record(&self, record_id: &str, bytes: &[u8]) -> AppResult<u64> {
        let path = self.record_path(record_id)?;
        write_atomic(&path, bytes).await?;
        Ok(bytes.len() as u64)
    }

    pub async fn read_record(&self, record_id: &str) -> AppResult<Option<Vec<u8>>> {
        read_all(&self.record_path(record_id)?).await
    }

    pub async fn read_record_range(
        &self,
        record_id: &str,
        offset: u64,
        limit: u64,
    ) -> AppResult<Option<(Vec<u8>, u64)>> {
        read_range(&self.record_path(record_id)?, offset, limit).await
    }

    pub async fn remove_record(&self, record_id: &str) -> AppResult<()> {
        let path = self.record_path(record_id)?;
        remove_if_present(&path).await
    }

    pub async fn write_handoff(&self, handoff_id: &str, bytes: &[u8]) -> AppResult<()> {
        let path = self.handoff_path(handoff_id)?;
        write_atomic(&path, bytes).await
    }

    pub async fn read_handoff(&self, handoff_id: &str) -> AppResult<Option<Vec<u8>>> {
        read_all(&self.handoff_path(handoff_id)?).await
    }

    pub async fn handoff_size(&self, handoff_id: &str) -> u64 {
        let Ok(path) = self.handoff_path(handoff_id) else {
            return 0;
        };
        tokio::fs::metadata(path)
            .await
            .map(|metadata| metadata.len())
            .unwrap_or(0)
    }

    pub async fn remove_handoff(&self, handoff_id: &str) -> AppResult<()> {
        let dir = self.root.join("handoffs").join(validate_id(handoff_id)?);
        remove_dir_if_present(&dir).await
    }

    pub async fn write_rule(&self, rule_id: &str, revision: u32, bytes: &[u8]) -> AppResult<()> {
        let path = self.rule_path(rule_id, revision)?;
        write_atomic(&path, bytes).await
    }

    pub async fn read_rule(&self, body_id: &str) -> AppResult<Option<Vec<u8>>> {
        let Some((rule_id, revision)) = body_id.split_once('/') else {
            return Ok(None);
        };
        let revision = revision
            .parse::<u32>()
            .map_err(|_| AppError::InvalidStoragePath(body_id.to_string()))?;
        read_all(&self.rule_path(rule_id, revision)?).await
    }

    /// The rule's sample body, captured when the rule was seeded.
    pub async fn write_rule_sample(
        &self,
        rule_id: &str,
        revision: u32,
        bytes: &[u8],
    ) -> AppResult<()> {
        let path = self.sample_path(rule_id, revision)?;
        write_atomic(&path, bytes).await?;
        Ok(())
    }

    pub async fn read_rule_sample(
        &self,
        rule_id: &str,
        revision: u32,
    ) -> AppResult<Option<Vec<u8>>> {
        read_all(&self.sample_path(rule_id, revision)?).await
    }

    pub async fn read_handoff_range(
        &self,
        handoff_id: &str,
        offset: u64,
        limit: u64,
    ) -> AppResult<Option<(Vec<u8>, u64)>> {
        read_range(&self.handoff_path(handoff_id)?, offset, limit).await
    }

    /// Removes `rules/` and `handoffs/` directories the database no longer
    /// knows about, including bodies left behind by earlier versions. Files modified
    /// within the last minute are kept, so a commit in flight is never deleted
    /// from under the transaction that just wrote it.
    pub async fn sweep_orphans(
        &self,
        live_rules: &[String],
        live_handoffs: &[String],
    ) -> AppResult<Vec<String>> {
        let mut removed = Vec::new();
        for (directory, live) in [("rules", live_rules), ("handoffs", live_handoffs)] {
            let parent = self.root.join(directory);
            let names = match tokio::fs::read_dir(&parent).await {
                Ok(mut entries) => {
                    let mut names = Vec::new();
                    loop {
                        match entries.next_entry().await {
                            Ok(None) => break,
                            Ok(Some(entry)) => {
                                names.push(entry.file_name().to_string_lossy().to_string())
                            }
                            Err(error) => {
                                return Err(AppError::Io {
                                    path: Some(parent.clone()),
                                    source: error,
                                });
                            }
                        }
                    }
                    names
                }
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
                Err(error) => {
                    return Err(AppError::Io {
                        path: Some(parent.clone()),
                        source: error,
                    });
                }
            };
            for name in names {
                if live.contains(&name) {
                    continue;
                }
                let path = parent.join(&name);
                let metadata = match tokio::fs::metadata(&path).await {
                    Ok(metadata) => metadata,
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
                    Err(error) => {
                        return Err(AppError::Io {
                            path: Some(path.clone()),
                            source: error,
                        });
                    }
                };
                if !metadata.is_dir() {
                    continue;
                }
                // Leave anything written in the last minute alone: a commit in
                // flight must not lose the file the transaction just wrote.
                let age = metadata
                    .modified()
                    .ok()
                    .and_then(|time| time.elapsed().ok())
                    .map(|age| age.as_secs())
                    .unwrap_or(u64::MAX);
                if age < 60 {
                    continue;
                }
                remove_dir_if_present(&path).await?;
                removed.push(format!("{directory}/{name}"));
            }
        }
        Ok(removed)
    }

    pub async fn read_rule_range(
        &self,
        body_id: &str,
        offset: u64,
        limit: u64,
    ) -> AppResult<Option<(Vec<u8>, u64)>> {
        let Some((rule_id, revision)) = body_id.split_once('/') else {
            return Ok(None);
        };
        let revision = revision
            .parse::<u32>()
            .map_err(|_| AppError::InvalidStoragePath(body_id.to_string()))?;
        read_range(&self.rule_path(rule_id, revision)?, offset, limit).await
    }

    pub async fn remove_rule(&self, rule_id: &str) -> AppResult<()> {
        let dir = self.root.join("rules").join(validate_id(rule_id)?);
        remove_dir_if_present(&dir).await
    }

    /// Capture stop, clear and server start all discard the transient buffer.
    pub async fn clear_tmp(&self) -> AppResult<()> {
        let dir = self.root.join("tmp");
        remove_dir_if_present(&dir).await?;
        tokio::fs::create_dir_all(&dir).await.with_path(&dir)?;
        set_private_dir(&dir).await;
        Ok(())
    }
}

fn validate_id(value: &str) -> AppResult<&str> {
    if value.is_empty()
        || value.len() > MAX_ID_LEN
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-')
    {
        return Err(AppError::InvalidStoragePath(value.to_string()));
    }
    Ok(value)
}

async fn write_atomic(path: &Path, bytes: &[u8]) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        tokio::fs::create_dir_all(parent).await.with_path(parent)?;
        set_private_dir(parent).await;
    }
    let temporary = path.with_extension("bin.tmp");
    {
        let mut file = tokio::fs::File::create(&temporary)
            .await
            .with_path(&temporary)?;
        file.write_all(bytes).await.with_path(&temporary)?;
        file.flush().await.with_path(&temporary)?;
    }
    set_private_file(&temporary).await;
    tokio::fs::rename(&temporary, path).await.with_path(path)?;
    Ok(())
}

async fn read_all(path: &Path) -> AppResult<Option<Vec<u8>>> {
    match tokio::fs::read(path).await {
        Ok(bytes) => Ok(Some(bytes)),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(AppError::Io {
            path: Some(path.to_path_buf()),
            source: error,
        }),
    }
}

async fn read_range(path: &Path, offset: u64, limit: u64) -> AppResult<Option<(Vec<u8>, u64)>> {
    let mut file = match tokio::fs::File::open(path).await {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(AppError::Io {
                path: Some(path.to_path_buf()),
                source: error,
            });
        }
    };
    let total = file
        .metadata()
        .await
        .map_err(|source| AppError::Io {
            path: Some(path.to_path_buf()),
            source,
        })?
        .len();
    let skip = offset.min(total);
    file.seek(std::io::SeekFrom::Start(skip))
        .await
        .map_err(|source| AppError::Io {
            path: Some(path.to_path_buf()),
            source,
        })?;
    let take = limit.min(total.saturating_sub(skip));
    let mut buffer = Vec::with_capacity(take as usize);
    file.take(take)
        .read_to_end(&mut buffer)
        .await
        .map_err(|source| AppError::Io {
            path: Some(path.to_path_buf()),
            source,
        })?;
    Ok(Some((buffer, total)))
}

async fn remove_if_present(path: &Path) -> AppResult<()> {
    match tokio::fs::remove_file(path).await {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(AppError::Io {
            path: Some(path.to_path_buf()),
            source: error,
        }),
    }
}

async fn remove_dir_if_present(path: &Path) -> AppResult<()> {
    match tokio::fs::remove_dir_all(path).await {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(AppError::Io {
            path: Some(path.to_path_buf()),
            source: error,
        }),
    }
}

#[cfg(unix)]
async fn set_private_dir(path: &Path) {
    use std::os::unix::fs::PermissionsExt;
    let _ = tokio::fs::set_permissions(path, std::fs::Permissions::from_mode(0o700)).await;
}

#[cfg(not(unix))]
async fn set_private_dir(_path: &Path) {}

#[cfg(unix)]
async fn set_private_file(path: &Path) {
    use std::os::unix::fs::PermissionsExt;
    let _ = tokio::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600)).await;
}

#[cfg(not(unix))]
async fn set_private_file(_path: &Path) {}

#[cfg(test)]
mod tests {
    #![allow(clippy::expect_used)]
    use super::*;

    #[tokio::test]
    async fn rejects_path_like_keys() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store = BodyStore::new(dir.path().join("network"))
            .await
            .expect("store");
        for key in ["../escape", "a/b", "", "x y"] {
            assert!(store.write_record(key, b"x").await.is_err(), "key {key}");
        }
        assert!(store.write_record("netrec_ok", b"x").await.is_ok());
    }

    #[tokio::test]
    async fn writes_are_atomic_and_ranges_are_bounded() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store = BodyStore::new(dir.path().join("network"))
            .await
            .expect("store");
        store
            .write_record("netrec_1", b"hello world")
            .await
            .expect("write");
        let (bytes, total) = store
            .read_record_range("netrec_1", 6, 100)
            .await
            .expect("read")
            .expect("present");
        assert_eq!(bytes, b"world");
        assert_eq!(total, 11);
        let (bytes, _) = store
            .read_record_range("netrec_1", 0, 3)
            .await
            .expect("read")
            .expect("present");
        assert_eq!(bytes, b"hel");
    }
}
